from __future__ import annotations

from dataclasses import dataclass

import pytest

from llm_router._api.types import Provider
from llm_router._internal.runtime.limiter import LimiterState
from llm_router._internal.runtime.router import RouterRuntime

pytestmark = pytest.mark.verification_kind("unit")


@dataclass
class RecordingExecutor:
    used_key_ids: list[int]

    def execute(self, request: object, **kwargs: object) -> object:
        self.used_key_ids.append(request.key.key_id)
        return "ok"


class FixedWaitLimiter(LimiterState):
    def __init__(self, waits: dict[int, float]) -> None:
        super().__init__()
        self.waits = waits

    def wait_seconds(self, *, provider: Provider, key_id: int) -> float:
        assert provider is Provider.OPENROUTER
        return self.waits[key_id]


@pytest.mark.verifies("TREQ_RATE_LIMIT_AVAILABILITY_SELECTION[revision==1]")
def test_all_blocked_executes_shortest_wait_key_first() -> None:
    used: list[int] = []
    runtime = RouterRuntime(
        spec="openrouter/model",
        executor=RecordingExecutor(used),
        key_id="auto",
    )
    assert isinstance(runtime, RouterRuntime)
    assert FixedWaitLimiter({1: 30.0, 2: 5.0, 3: 60.0}).wait_seconds(
        provider=Provider.OPENROUTER, key_id=2
    ) == 5.0
